KG42.register("clusters-15877254586463be6d4f381c",{"id":"24-brooklyn_microgrid::v142-d-K002","paper":"24-brooklyn_microgrid","label":"Current electricity trading products and planned thermal energy expansion","record":{"cluster_id":"v142-d-K002","label":"Current electricity trading products and planned thermal energy expansion","market_meaning":"Market setup needs to define the form of energy traded; at the reporting stage, the BMG permits only electricity trading, and thermal energy belongs to a future expansion plan.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["bidding"],"scope_disposition":"conditional","scope_explanation":"The energy forms listed in the general framework, the BMG's current electricity restriction, and the future thermal energy plan apply separately. The future plan does not expand the currently tradable products, nor does it automatically inherit existing electricity order, pricing, or settlement rules.","assembly_status":"assembled","boundary_rationale":"The traded-product restriction has independent market meaning; the single chain already includes the setup requirement, current applicable conditions, and permitted products, and it need not be merged into participant access because of a shared market setup background.","chain_bindings":[{"chain_id":"v141-c-R011","ownership":"primary","role":"core","rationale":"Fully retain the general product definition, the current electricity restriction, and the different conditions of the future thermal energy plan."}],"connections":[],"object_mappings":[],"gaps":[{"gap_id":"v142-d-K002-G01","category":"upstream_missing","description":"Thermal energy appears only as a future plan, and no implementation time point, product specification, or corresponding rule with the existing electricity trading process is provided. This gap does not change the candidate restriction that currently only electricity is traded.","chain_ids":["v141-c-R011"],"object_refs":["v141-c-R011::phi::v141-c-R011-C003","v141-c-R011::phi::v141-c-R011-C004"],"evidence_ids":["v141-b-g02-e02","v141-b-g02-e03"],"proposal_ids":[],"required_work":"If a future thermal energy market is to be covered, the basis for implementation and product definition should be obtained separately, and then C should establish the corresponding content; the plan is not treated as an operating rule."},{"gap_id":"v142-d-K002-G02","category":"unverified_source","description":"The traded-product citation has not undergone independent B source review, and its current status remains unverified.","chain_ids":["v141-c-R011"],"object_refs":[],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E04","v141-b-g02-e02","v141-b-g02-e03"],"proposal_ids":[],"required_work":"Manually check the original-text qualifications of the current stage and the future plan; this assembly does not mean that the product rules have obtained scientific acceptance."}]},"rule_refs":["24-brooklyn_microgrid::v141-c-R011"],"unresolved_rule_refs":[],"node_ids":["KG31-f7b61cd71d590dc0"]});
